#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <chrono>
#include <random>
using namespace std;

struct Result { int totalWays, totalSum; Result() : totalWays(0), totalSum(0) {} Result(int w, int s) : totalWays(w), totalSum(s) {} };

int totalComponents, totalPersons, modulus;
vector<vector<int>> choose;

int sumRange(int start, int end) { return (start + end) * (end - start + 1) / 2; }

vector<bool> computed2;
vector<Result> memo2;

Result compute2(int n) {
    if (n == 1) return Result(2, 0);
    if (computed2[n]) return memo2[n];
    Result res(0, 0);
    for (int i = 0; i < n; ++i) {
        int leftCount = i, rightCount = n - i - 1;
        Result leftRes = (leftCount == 0) ? Result(1, 0) : compute2(leftCount);
        Result rightRes = (rightCount == 0) ? Result(1, 0) : compute2(rightCount);
        int ways = (leftCount + 1) + (rightCount + 1);
        int sumAdd = sumRange(0, leftCount) + sumRange(0, rightCount);
        int mlt = choose[leftCount + rightCount][leftCount];
        res.totalWays = (res.totalWays + (long long)leftRes.totalWays * ways % modulus * rightRes.totalWays % modulus * mlt) % modulus;
        res.totalSum = (res.totalSum + (long long)leftRes.totalSum * ways % modulus * rightRes.totalWays % modulus * mlt
                        + (long long)leftRes.totalWays * sumAdd % modulus * rightRes.totalWays % modulus * mlt
                        + (long long)leftRes.totalWays * ways % modulus * rightRes.totalSum % modulus * mlt) % modulus;
    }
    computed2[n] = true;
    memo2[n] = res;
    return res;
}

vector<vector<bool>> computed1;
vector<vector<Result>> memo1;

Result compute1(int index, int count) {
    if (totalComponents - index == count) return compute2(count);
    if (computed1[index][count]) return memo1[index][count];
    Result res(0, 0);
    for (int i = index; i < totalComponents; ++i) {
        int leftCount = i - index;
        int rightCount = count - leftCount;
        if (rightCount < 0 || rightCount > totalComponents - i - 1) continue;
        Result leftRes = (i == index) ? Result(1, 0) : compute2(leftCount);
        Result rightRes = (i + 1 == totalComponents) ? Result(1, 0) : compute1(i + 1, rightCount);
        int mlt = choose[leftCount + rightCount][leftCount];
        res.totalWays = (res.totalWays + (long long)leftRes.totalWays * rightRes.totalWays % modulus * mlt) % modulus;
        res.totalSum = (res.totalSum + (long long)leftRes.totalSum * rightRes.totalWays % modulus * mlt
                        + (long long)leftRes.totalWays * rightRes.totalSum % modulus * mlt) % modulus;
    }
    computed1[index][count] = true;
    memo1[index][count] = res;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ncomp, npers, MOD;
    cin >> ncomp >> npers >> MOD;
    totalComponents = ncomp;
    totalPersons = npers;
    modulus = MOD;
    choose.assign(ncomp + 1, vector<int>(ncomp + 1, 0));
    for (int i = 0; i <= ncomp; ++i) {
        choose[i][0] = 1;
        choose[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;
        }
    }
    computed2.assign(ncomp + 1, false);
    memo2.assign(ncomp + 1, Result());
    computed1.assign(ncomp + 1, vector<bool>(npers + 1, false));
    memo1.assign(ncomp + 1, vector<Result>(npers + 1));
    cout << compute1(0, npers).totalSum << "\n";
    return 0;
}
